 if(returnDraft){const d=returnDraft,c=await record("contract",d.contractId),e=await record("edition",d.editionId);
 html+=panel("Bind each original returned column",body(form('<div class="form-grid">'+select("Receiving source","kind",[{value:"supplier-export",label:"Actual supplier/target export"},{value:"owned-local-export",label:"Owned local receiving example"}],d.kind,null)+field("Return evidence reference","basis",d.basis,{required:true})+'</div>'+
 d.tables.map((mapping,i)=>{const m=c.definition.tables.find(x=>x.id===mapping.mappingId),t=e.tables.find(t=>t.id===mapping.tableId),p="return"+i+"-";return details(m.id+" → "+m.target.table,
 withChange(select("Actual returned table",p+"table",e.tables.map(x=>({value:x.id,label:x.name+" · "+fmt(x.rows)+" rows"})),t.id,null),async event=>{readReturnForm();const next=e.tables.find(x=>x.id===event.target.value);mapping.tableId=next.id;mapping.fields=Object.fromEntries(m.target.columns.map(col=>[col.name,next.headers.includes(col.name)?next.headers.indexOf(col.name):null]));mapping.identityColumn=null;mapping.versionColumn=null;mapping.dispositionColumn=null;await render();})+
 table(["Agreed target field","Returned source column"],m.target.columns.map((col,j)=>[esc(col.name),selectBare(p+"field"+j,headersOptions(t.headers),mapping.fields[col.name]??"")]))+
 '<div class="form-grid three">'+select("Actual target record ID",p+"identity",headersOptions(t.headers),mapping.identityColumn??"","No returned identity column")+select("Actual target record version",p+"version",headersOptions(t.headers),mapping.versionColumn??"","No returned version column")+select("Per-row returned disposition",p+"disposition",headersOptions(t.headers),mapping.dispositionColumn??"","No per-row disposition")+'</div>'+
 '<div class="form-grid">'+["accepted","rejected","pending","unknown"].map(k=>field("Exact returned strings meaning "+k,p+k,mapping.dispositions[k].join("\n"),{type:"textarea",note:"One original string per line. No default acceptance is inferred."})).join("")+"</div>",true);}).join("")+
 button("Use this example's actual local return columns",async()=>{readReturnForm();returnDraft.kind="owned-local-export";returnDraft.tables.forEach(x=>{const t=e.tables.find(t=>t.id===x.tableId);for(const[k,h]of[["identityColumn","_local_record_id"],["versionColumn","_local_version"],["dispositionColumn","_local_disposition"]]){if(!t.headers.includes(h))throw new Error("The selected original table does not contain "+h);x[k]=t.headers.indexOf(h);}x.dispositions={accepted:["accepted"],rejected:[],pending:[],unknown:[]};});await render();},"small")+
 '<div class="section-space">'+check("This is a complete export of the entire agreed target scope","complete",d.completeSnapshot)+field("Scope, cutoff and completeness evidence","coverage",d.coverageNote,{type:"textarea",required:true})+'</div><div class="actions">'+submit("Retain actual target return")+button("Close mapping",async()=>{returnDraft=null;await render();},"quiet")+"</div>",
 async()=>{readReturnForm();const r=await mutate("import-target-return",returnDraft);selection("targetReturn",r.id);returnDraft=null;await render();},' id="return-editor"')));
 }
 const id=chosen("targetReturn",returns),r=await record("target-return",id);if(id)selection("targetReturn",id);
 if(r){html+=panel("Returned identity and snapshot",body(withChange(select("Retained target return","return",recordOptions(returns),id,null),async event=>{selection("targetReturn",event.target.value);await render();})+
 '<div class="status-line">'+badge(r.ready?"UNAMBIGUOUS RETURN":"RETURN FINDINGS",r.ready?"dark":"warn")+badge(r.completeSnapshot?"COMPLETE AGREED SCOPE":"PARTIAL EXPORT",r.completeSnapshot?"":"warn")+badge(fmt(r.rows)+" rows","plain")+statusCounts(r.dispositions)+'</div>'+
 '<p class="muted section-space">'+esc(r.acceptance)+'</p><dl class="record-grid"><dt>Snapshot SHA256</dt><dd class="mono">'+esc(r.snapshotSha256)+'</dd><dt>Source evidence</dt><dd>'+esc(typeof r.basis==="string"?r.basis:json(r.basis))+'</dd><dt>Scope</dt><dd>'+esc(r.coverageNote)+'</dd></dl>'+artifacts(r)+recordButton("target-return",id,"Inspect returned field mapping and findings")+
 form('<div class="section-space">'+field("Why this exact target snapshot is an accepted baseline","reason","",{required:true,type:"textarea"})+'</div><div class="actions">'+submit("Accept exact target baseline")+"</div>",async form=>{await mutate("accept-baseline",{returnId:r.id,snapshotSha256:r.snapshotSha256,reason:value(form,"reason")});await render();})));
 }
 if(baselines.length)html+=panel("Accepted original baselines",table(["Baseline","Returned edition","Snapshot","Review"],baselines.map(b=>[recordButton("baseline",b.id),recordButton("target-return",b.returnId),'<span class="mono">'+esc(short(b.snapshotSha256))+"</span>",esc(b.reason)])));
