function readReturnForm(){const form=$("#return-editor");if(!form||!returnDraft)return;const d=returnDraft;d.kind=value(form,"kind");d.basis=value(form,"basis");d.completeSnapshot=checked(form,"complete");d.coverageNote=value(form,"coverage");
 d.tables.forEach((m,i)=>{const p="return"+i+"-";m.tableId=value(form,p+"table");Object.keys(m.fields).forEach((h,j)=>{const v=value(form,p+"field"+j);m.fields[h]=v===""?null:Number(v);});
 for(const[k,n]of[["identityColumn","identity"],["versionColumn","version"],["dispositionColumn","disposition"]])m[k]=value(form,p+n)===""?null:Number(value(form,p+n));
 for(const k of["accepted","rejected","pending","unknown"])m.dispositions[k]=value(form,p+k).split("\n").filter(x=>x!=="");});
}

