 '<span class="mono">'+esc(r.mappingId)+"</span><br>"+esc(r.key.join(" · ")),
 esc(Array.isArray(r.changes)?r.changes.map(x=>typeof x==="object"?(x.field||x.header||json(x)):x).join(", "):json(r.changes||{})),
 button("Inspect original comparison row",()=>dialog(r.status+" · "+r.key.join(" / "),'<pre>'+esc(json(r))+"</pre>"),"small")
